result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/build.js", "content": "// Design-token pipeline: token JSON -> CSS custom properties (light + dark)
// plus WCAG contrast checking.

/** Convert #rgb / #rrggbb to { r, g, b } in [0,255]. Throws on bad input. */
export function hexToRgb(hex) {
  let h = hex.replace(/^#/, '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  if (!/^[0-9a-fA-F]{6}$/.test(h)) throw new Error(`Invalid hex color: ${hex}`);
  return {
    r: parseInt(h.slice(0, 2), 16),
    g: parseInt(h.slice(2, 4), 16),
    b: parseInt(h.slice(4, 6), 16),
  };
}

/** WCAG relative luminance. */
export function luminance(hex) {
  const { r, g, b } = hexToRgb(hex);
  const chan = (v) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * chan(r) + 0.7152 * chan(g) + 0.0722 * chan(b);
}

/** WCAG contrast ratio between two hex colors, rounded to 2 decimals. */
export function contrast(a, b) {
  const la = luminance(a);
  const lb = luminance(b);
  const ratio = (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
  return Math.round(ratio * 100) / 100;
}

const MIN_RATIO = 4.5;
const FOREGROUND = ['text', 'muted'];
const BACKGROUND = ['bg', 'surface'];

/**
 * Compute WCAG contrast failures for text/muted against bg/surface
 * in both themes.
 *
 * @returns {Array<{theme:string, foreground:string, background:string, ratio:number, min:number}>}
 */
export function check(tokens) {
  const failures = [];
  for (const theme of Object.keys(tokens)) {
    const set = tokens[theme];
    for (const fg of FOREGROUND) {
      for (const bg of BACKGROUND) {
        if (!(fg in set) || !(bg in set)) continue;
        const ratio = contrast(set[fg], set[bg]);
        if (ratio < MIN_RATIO) {
          failures.push({ theme, foreground: fg, background: bg, ratio, min: MIN_RATIO });
        }
      }
    }
  }
  return failures;
}

function declarations(set) {
  return Object.entries(set)
    .map(([name, value]) => `  --color-${name}: ${value};`)
    .join('\n');
}

/**
 * Emit CSS custom properties:
 *   :root with the light theme, overridden inside a
 *   prefers-color-scheme: dark media block.
 */
export function toCss(tokens) {
  const light = tokens.light ?? {};
  const dark = tokens.dark ?? {};
  return [
    ':root {\n' + declarations(light) + '\n}\n',
    '@media (prefers-color-scheme: dark) {\n:root {\n' + declarations(dark) + '\n}\n}\n',
  ].join('\n');
}
"})
