result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/build.test.js", "content": "import { readFileSync } from 'node:fs';
import postcss from 'postcss';
import { describe, it, expect } from 'vitest';
import { toCss, check, contrast } from '../src/build.js';

const tokens = JSON.parse(readFileSync(new URL('../tokens/tokens.json', import.meta.url), 'utf8'));

// Deliberately failing palette: muted-on-surface is far too low contrast.
const failingTokens = {
  light: { bg: '#eeeeee', surface: '#f5f5f5', text: '#111111', muted: '#c0c0c0', accent: '#2563eb' },
  dark: tokens.dark,
};

function decls(root) {
  const out = {};
  root.walkDecls((d) => { out[d.prop] = d.value; });
  return out;
}

describe('toCss', () => {
  const css = toCss(tokens);
  const rootAst = postcss.parse(css);

  it('emits a :root block with --color-* variables for the light theme', () => {
    const rules = rootAst.nodes.filter((n) => n.type === 'rule' && n.selector === ':root');
    expect(rules).toHaveLength(1);

    for (const [name, value] of Object.entries(tokens.light)) {
      expect(rules[0].nodes).toContainEqual(
        expect.objectContaining({ prop: `--color-${name}`, value })
      );
    }
    // All variable names present, nothing extra.
    const names = rules[0].nodes.map((d) => d.prop);
    expect(names.sort()).toEqual(
      Object.keys(tokens.light).map((n) => `--color-${n}`).sort()
    );
  });

  it('overrides variables in a prefers-color-scheme: dark media block', () => {
    const media = rootAst.nodes.find(
      (n) => n.type === 'atrule' && n.name === 'media' && n.params === '(prefers-color-scheme: dark)'
    );
    expect(media).toBeDefined();

    const innerRoot = media.nodes.filter((n) => n.type === 'rule' && n.selector === ':root');
    expect(innerRoot).toHaveLength(1);
    expect(decls(innerRoot[0])).toEqual(
      Object.fromEntries(Object.entries(tokens.dark).map(([k, v]) => [`--color-${k}`, v]))
    );
  });

  it('does not leak light values into the dark block', () => {
    const cssDarkOnly = toCss({ light: {}, dark: tokens.dark });
    const ast = postcss.parse(cssDarkOnly);
    let sawMedia = false;
    ast.walkAtRules('media', (m) => {
      sawMedia ||= m.params === '(prefers-color-scheme: dark)';
    });
    expect(sawMedia).toBe(true);
  });
});

describe('check', () => {
  it('returns an empty failure list for the shipped palette', () => {
    expect(check(tokens)).toEqual([]);
  });

  it('catches every below-4.5 pairing in a deliberately failing palette', () => {
    const failures = check(failingTokens);
    expect(failures).toContainEqual({
      theme: 'light',
      foreground: 'muted',
      background: 'bg',
      ratio: contrast(failingTokens.light.muted, failingTokens.light.bg),
      min: 4.5,
    });
    expect(failures).toContainEqual(
      expect.objectContaining({ theme: 'light', foreground: 'muted', background: 'surface' })
    );
    // Sanity: the fixture really is sub-AA.
    expect(contrast(failingTokens.light.muted, failingTokens.light.bg)).toBeLessThan(4.5);
    // And text still passes there, so the failure is specific.
    expect(failures.every((f) => f.foreground !== 'text')).toBe(true);
  });
});
"})
